-- Open-flow board test (Basys2-250): the Clocking Wizard's module (#793, clkgen.vhd, generated by
-- core/clocking.js): a DCM_SP on the 50 MHz clock (B8), CLK0 (the feedback), CLK2X (100 MHz), CLKDV
-- (12.5 MHz) and CLKFX (65 MHz, x 13 / 10), each on a global buffer, RST from BTN0, LOCKED; a counter on
-- each clock:
--   LD0  CLK0   (bit 24: about 0.67 s per on-off cycle)
--   LD1  CLK2X  (about 0.34 s)
--   LD2  CLKDV  (bit 22: about 0.67 s)
--   LD3  CLKFX  (bit 24: about 0.52 s)
--   LD7  LOCKED (on when the DCM has locked; off while BTN0 is held)
-- sw(0) = 1 holds the counters.
library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD.ALL;

entity top is
  port (clk : in  std_logic;
        btn : in  std_logic_vector(0 downto 0);
        sw  : in  std_logic_vector(0 downto 0);
        led : out std_logic_vector(7 downto 0));
end top;

architecture rtl of top is
  signal clk0, clk2x, clkdv, clkfx, locked : std_logic;
  signal n0, n2x, nfx : unsigned(24 downto 0) := (others => '0');
  signal ndv : unsigned(22 downto 0) := (others => '0');
  signal h0, h2x, hdv, hfx : std_logic := '0';
begin
  u_clk : entity work.clkgen port map (clk_in => clk, rst => btn(0), clk0 => clk0, clk2x => clk2x, clkdv => clkdv, clkfx => clkfx, locked => locked);

  -- (the switch is synchronised to each clock)
  process (clk0) begin if rising_edge(clk0) then h0 <= sw(0); if h0 = '0' then n0 <= n0 + 1; end if; end if; end process;
  process (clk2x) begin if rising_edge(clk2x) then h2x <= sw(0); if h2x = '0' then n2x <= n2x + 1; end if; end if; end process;
  process (clkdv) begin if rising_edge(clkdv) then hdv <= sw(0); if hdv = '0' then ndv <= ndv + 1; end if; end if; end process;
  process (clkfx) begin if rising_edge(clkfx) then hfx <= sw(0); if hfx = '0' then nfx <= nfx + 1; end if; end if; end process;

  led <= locked & "000" & nfx(24) & ndv(22) & n2x(24) & n0(24);
end rtl;
